PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT OR IGNORE INTO app_meta VALUES ('revision','0');
CREATE TABLE providers (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE people (id TEXT PRIMARY KEY, display_name TEXT NOT NULL, relationship TEXT, is_patient INTEGER NOT NULL DEFAULT 0 CHECK(is_patient IN (0,1)));
INSERT INTO people VALUES ('patient','Patient',NULL,1);
CREATE TABLE manual_batches (id TEXT PRIMARY KEY, title TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('in_progress','verified','unresolved')), created_at TEXT NOT NULL, verified_at TEXT, notes TEXT NOT NULL DEFAULT '', coverage_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(coverage_json)));
CREATE TABLE source_files (id TEXT PRIMARY KEY, provider_id TEXT REFERENCES providers(id), path TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, bytes INTEGER NOT NULL CHECK(bytes>=0), mime_type TEXT NOT NULL DEFAULT 'application/octet-stream', kind TEXT NOT NULL DEFAULT 'source', coverage_status TEXT NOT NULL DEFAULT 'retained', batch_id TEXT REFERENCES manual_batches(id), details_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(details_json)));
CREATE TABLE source_records (id TEXT PRIMARY KEY, source_file_id TEXT NOT NULL REFERENCES source_files(id), provider_id TEXT REFERENCES providers(id), source_key TEXT, kind TEXT NOT NULL DEFAULT 'unclassified', label TEXT, date_text TEXT, raw_json TEXT NOT NULL CHECK(json_valid(raw_json)), locator_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(locator_json)), extraction_status TEXT NOT NULL DEFAULT 'retained', batch_id TEXT REFERENCES manual_batches(id), UNIQUE(source_file_id,source_key));
CREATE INDEX source_records_kind ON source_records(kind,provider_id);
CREATE TABLE record_relationships (id TEXT PRIMARY KEY, from_record_id TEXT NOT NULL REFERENCES source_records(id), to_record_id TEXT NOT NULL REFERENCES source_records(id), relation TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('proposed','accepted','rejected')), rationale TEXT NOT NULL, UNIQUE(from_record_id,to_record_id,relation));
CREATE TABLE reports (id TEXT PRIMARY KEY, source_record_id TEXT REFERENCES source_records(id), provider_id TEXT REFERENCES providers(id), title TEXT NOT NULL, effective_at TEXT, status TEXT, extra_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(extra_json)));
CREATE TABLE test_types (id TEXT PRIMARY KEY, label TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'Laboratory', unit TEXT, aliases_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(aliases_json)), codes_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(codes_json)), context TEXT, extra_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(extra_json)));
CREATE TABLE observations (id TEXT PRIMARY KEY, test_type_id TEXT NOT NULL REFERENCES test_types(id), person_id TEXT NOT NULL DEFAULT 'patient' REFERENCES people(id), provider_id TEXT REFERENCES providers(id), source_record_id TEXT NOT NULL REFERENCES source_records(id), report_id TEXT REFERENCES reports(id), label TEXT NOT NULL, effective_at TEXT, date_precision TEXT NOT NULL DEFAULT 'unknown', value_text TEXT NOT NULL, value_numeric REAL, comparator TEXT, unit TEXT, reference_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(reference_json)), status TEXT, extra_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(extra_json)));
CREATE INDEX observations_type_date ON observations(test_type_id,effective_at,id);
CREATE TABLE medications (id TEXT PRIMARY KEY, source_record_id TEXT NOT NULL REFERENCES source_records(id), provider_id TEXT REFERENCES providers(id), person_id TEXT NOT NULL DEFAULT 'patient' REFERENCES people(id), kind TEXT NOT NULL CHECK(kind IN ('order','reported_use','dispense','administration','unknown')), label TEXT NOT NULL, status TEXT, dose_text TEXT, route TEXT, frequency TEXT, start_at TEXT, end_at TEXT, extra_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(extra_json)));
CREATE TABLE procedures (id TEXT PRIMARY KEY, source_record_id TEXT NOT NULL REFERENCES source_records(id), provider_id TEXT REFERENCES providers(id), person_id TEXT NOT NULL DEFAULT 'patient' REFERENCES people(id), label TEXT NOT NULL, effective_at TEXT, status TEXT, extra_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(extra_json)));
CREATE TABLE documents (id TEXT PRIMARY KEY, source_record_id TEXT NOT NULL REFERENCES source_records(id), provider_id TEXT REFERENCES providers(id), title TEXT NOT NULL, effective_at TEXT, text_content TEXT, extra_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(extra_json)));
CREATE TABLE evidence (id TEXT PRIMARY KEY, entity_type TEXT NOT NULL CHECK(entity_type IN ('observation','medication','procedure','report','document','note','person')), entity_id TEXT NOT NULL, source_record_id TEXT NOT NULL REFERENCES source_records(id), role TEXT NOT NULL DEFAULT 'source', locator_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(locator_json)), UNIQUE(entity_type,entity_id,source_record_id,role));
CREATE TABLE notes (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('note','historical','person')), status TEXT NOT NULL CHECK(status IN ('editable','draft','finished')), title TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', note_type TEXT, event_date TEXT, topics TEXT NOT NULL DEFAULT '', raw_thoughts TEXT NOT NULL DEFAULT '', person_id TEXT UNIQUE REFERENCES people(id), profile_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(profile_json)), pinned INTEGER NOT NULL DEFAULT 0 CHECK(pinned IN (0,1)), archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), source_record_id TEXT REFERENCES source_records(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, finished_at TEXT, version INTEGER NOT NULL DEFAULT 1, CHECK((kind='historical' AND status IN ('draft','finished')) OR (kind IN ('note','person') AND status='editable')), CHECK((status='finished' AND finished_at IS NOT NULL) OR (status!='finished' AND finished_at IS NULL)), CHECK((kind='person' AND person_id IS NOT NULL) OR (kind!='person' AND person_id IS NULL)));
CREATE INDEX notes_kind_type ON notes(kind,note_type,updated_at);
CREATE TABLE note_links (id TEXT PRIMARY KEY, note_id TEXT NOT NULL REFERENCES notes(id), target_type TEXT NOT NULL CHECK(target_type IN ('note','person','observation','medication','procedure','source','document')), target_id TEXT NOT NULL, relation TEXT NOT NULL DEFAULT 'related', UNIQUE(note_id,target_type,target_id,relation));
CREATE INDEX note_links_target ON note_links(target_type,target_id);
CREATE TABLE assets (id TEXT PRIMARY KEY, original_name TEXT NOT NULL, stored_path TEXT NOT NULL, mime_type TEXT NOT NULL, bytes INTEGER NOT NULL CHECK(bytes>=0), sha256 TEXT NOT NULL, created_at TEXT NOT NULL, attribution TEXT NOT NULL DEFAULT 'user-uploaded', source_file_id TEXT REFERENCES source_files(id), UNIQUE(stored_path));
CREATE TABLE attachments (id TEXT PRIMARY KEY, asset_id TEXT NOT NULL REFERENCES assets(id), owner_type TEXT NOT NULL CHECK(owner_type IN ('note','person','observation','medication','procedure','document')), owner_id TEXT NOT NULL, caption TEXT NOT NULL DEFAULT '', body_location TEXT, event_date TEXT, person_id TEXT REFERENCES people(id), created_at TEXT NOT NULL);
CREATE INDEX attachments_owner ON attachments(owner_type,owner_id);
CREATE TRIGGER notes_finished_update BEFORE UPDATE ON notes WHEN OLD.status='finished' BEGIN SELECT RAISE(ABORT,'Finished notes cannot be changed'); END;
CREATE TRIGGER notes_finished_delete BEFORE DELETE ON notes WHEN OLD.status='finished' BEGIN SELECT RAISE(ABORT,'Finished notes cannot be deleted'); END;
CREATE TRIGGER note_links_finished_insert BEFORE INSERT ON note_links WHEN EXISTS(SELECT 1 FROM notes WHERE id=NEW.note_id AND status='finished') BEGIN SELECT RAISE(ABORT,'Finished note links cannot be changed'); END;
CREATE TRIGGER note_links_finished_update BEFORE UPDATE ON note_links WHEN EXISTS(SELECT 1 FROM notes WHERE id IN (OLD.note_id,NEW.note_id) AND status='finished') BEGIN SELECT RAISE(ABORT,'Finished note links cannot be changed'); END;
CREATE TRIGGER note_links_finished_delete BEFORE DELETE ON note_links WHEN EXISTS(SELECT 1 FROM notes WHERE id=OLD.note_id AND status='finished') BEGIN SELECT RAISE(ABORT,'Finished note links cannot be changed'); END;
CREATE TRIGGER attachment_finished_insert BEFORE INSERT ON attachments WHEN NEW.owner_type='note' AND EXISTS(SELECT 1 FROM notes WHERE id=NEW.owner_id AND status='finished') BEGIN SELECT RAISE(ABORT,'Finished note attachments cannot be changed'); END;
CREATE TRIGGER attachment_finished_update BEFORE UPDATE ON attachments WHEN (OLD.owner_type='note' AND EXISTS(SELECT 1 FROM notes WHERE id=OLD.owner_id AND status='finished')) OR (NEW.owner_type='note' AND EXISTS(SELECT 1 FROM notes WHERE id=NEW.owner_id AND status='finished')) BEGIN SELECT RAISE(ABORT,'Finished note attachments cannot be changed'); END;
CREATE TRIGGER attachment_finished_delete BEFORE DELETE ON attachments WHEN OLD.owner_type='note' AND EXISTS(SELECT 1 FROM notes WHERE id=OLD.owner_id AND status='finished') BEGIN SELECT RAISE(ABORT,'Finished note attachments cannot be changed'); END;
INSERT INTO schema_migrations VALUES (1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
